33	enum SdkType {
34	  iPhone,
35	  iPhoneSimulator,
36	  macOS,
37	}
38	
39	/// SDK name passed to `xcrun --sdk`. Corresponds to undocumented Xcode
40	/// SUPPORTED_PLATFORMS values.
41	///
42	/// Usage: xcrun [options] <tool name> ... arguments ...
43	/// ...
44	/// --sdk <sdk name>            find the tool for the given SDK name.
45	String getNameForSdk(SdkType sdk) {
46	  switch (sdk) {
47	    case SdkType.iPhone:
48	      return 'iphoneos';
49	    case SdkType.iPhoneSimulator:
50	      return 'iphonesimulator';
51	    case SdkType.macOS:
52	      return 'macosx';
53	  }
54	  assert(false);
55	  return null;
56	}
